#include "zlang/Semantic.h"
namespace zlang {void SemanticAnalyzer::push(){scopes_.emplace_back();}void SemanticAnalyzer::pop(){scopes_.pop_back();}std::optional<SemanticAnalyzer::Var>SemanticAnalyzer::find(const std::string&n)const{for(auto i=scopes_.rbegin();i!=scopes_.rend();++i)if(auto x=i->find(n);x!=i->end())return x->second;return{};}bool SemanticAnalyzer::compatible(Type a,Type b)const{return a==b||(a==Type::Box&&b==Type::Box)||a==Type::Unknown||b==Type::Unknown;}bool SemanticAnalyzer::analyze(Program&p){int mains=0;for(auto&f:p.functions){if(funcs_.count(f->name))d_.error(f->span,"duplicate function '"+f->name+"'");else funcs_[f->name]=f.get();if(f->name=="main"){++mains;if(!f->params.empty())d_.error(f->span,"main cannot have parameters");}}if(mains==0)d_.error({},"program requires exactly one main function");for(auto&f:p.functions){current_=f.get();push();for(auto&x:f->params)scopes_.back()[x]={Type::Unknown,false};Type ret=Type::Void;for(auto&s:f->body->statements)stmt(*s,ret);f->returnType=ret;pop();}return!d_.hasErrors();}
void SemanticAnalyzer::stmt(Stmt&s,Type&ret){if(auto*x=dynamic_cast<VarDecl*>(&s)){for(auto&i:scopes_)if(i.count(x->name)){d_.error(x->span,"duplicate or shadowed variable '"+x->name+"'");return;}auto t=expr(*x->init);if(!compatible(x->type,t))d_.error(x->span,"initializer type does not match variable type");scopes_.back()[x->name]={x->type,false};}else if(auto*x=dynamic_cast<Assign*>(&s)){auto v=find(x->name);if(!v)d_.error(x->span,"use of undeclared variable '"+x->name+"'");else if(v->readonly)d_.error(x->span,"cannot assign to read-only for variable");else if(!compatible(v->type,expr(*x->value)))d_.error(x->span,"assignment type mismatch");}else if(auto*x=dynamic_cast<Print*>(&s)){for(auto&a:x->args)expr(*a);}else if(auto*x=dynamic_cast<If*>(&s)){if(expr(*x->cond)!=Type::Bool)d_.error(x->cond->span,"if condition must be bool");push();for(auto&a:x->thenBlock->statements)stmt(*a,ret);pop();for(auto&b:x->elseIfs){if(expr(*b.first)!=Type::Bool)d_.error(b.first->span,"else-if condition must be bool");push();for(auto&a:b.second->statements)stmt(*a,ret);pop();}if(x->elseBlock){push();for(auto&a:x->elseBlock->statements)stmt(*a,ret);pop();}}else if(auto*x=dynamic_cast<While*>(&s)){if(expr(*x->cond)!=Type::Bool)d_.error(x->cond->span,"while condition must be bool");push();for(auto&a:x->body->statements)stmt(*a,ret);pop();}else if(auto*x=dynamic_cast<For*>(&s)){if(expr(*x->end)!=Type::Box)d_.error(x->end->span,"for range must be box");push();scopes_.back()[x->name]={Type::Box,true};for(auto&a:x->body->statements)stmt(*a,ret);pop();}else if(auto*x=dynamic_cast<Return*>(&s)){Type t=x->value?expr(*x->value):Type::Void;if(ret==Type::Void)ret=t;else if(!compatible(ret,t))d_.error(x->span,"incompatible function return types");}else if(auto*x=dynamic_cast<ExprStmt*>(&s))expr(*x->expr,false);}
Type SemanticAnalyzer::expr(Expr&e,bool value){Type t=Type::Unknown;if(auto*x=dynamic_cast<LiteralExpr*>(&e)){t=std::holds_alternative<std::string>(x->value)?Type::Line:std::holds_alternative<bool>(x->value)?Type::Bool:Type::Box;}else if(auto*x=dynamic_cast<NameExpr*>(&e)){auto v=find(x->name);if(!v)d_.error(x->span,"use of undeclared variable '"+x->name+"'");else t=v->type;}else if(auto*x=dynamic_cast<UnaryExpr*>(&e)){t=expr(*x->rhs);if(t!=Type::Box)d_.error(x->span,"unary operator requires box");}else if(auto*x=dynamic_cast<BinaryExpr*>(&e)){auto a=expr(*x->lhs),b=expr(*x->rhs);if(x->op=="=="||x->op=="!="){if(!compatible(a,b))d_.error(x->span,"comparison type mismatch");t=Type::Bool;}else if(x->op=="<"||x->op=="<="||x->op==">"||x->op==">="){if(a!=Type::Box||b!=Type::Box)d_.error(x->span,"ordered comparison requires box");t=Type::Bool;}else if(a==Type::Unknown||b==Type::Unknown)t=Type::Unknown;else if(x->op=="+"&&a==Type::Line&&b==Type::Line)t=Type::Line;else if(a==Type::Box&&b==Type::Box)t=Type::Box;else if(a==Type::Cpx&&b==Type::Cpx)t=Type::Cpx;else d_.error(x->span,"invalid operands for '"+x->op+"'");}else if(auto*x=dynamic_cast<CallExpr*>(&e)){if(x->callee=="cpx"){if(x->args.size()!=2)d_.error(x->span,"cpx requires exactly 2 arguments");for(auto&a:x->args)if(expr(*a)!=Type::Box)d_.error(a->span,"cpx arguments must be box");t=Type::Cpx;}else if(auto f=funcs_.find(x->callee);f==funcs_.end())d_.error(x->span,"unknown function '"+x->callee+"'");else{if(x->args.size()!=f->second->params.size())d_.error(x->span,"function argument count mismatch");for(auto&a:x->args)expr(*a);t=f->second->returnType;}}if(value&&t==Type::Void)d_.error(e.span,"void function result used as a value");e.inferred=t;return t;}}

